export const specFinderToolsMd = "# Packrift Spec Finder Tools\n\nUpdated: 2026-07-11\n\nPackrift's MCP endpoint is `https://mcp.packrift.com/mcp`. Tools are read-only until cart URL handoff and are gated to approved catalog products.\n\n## Recommended Tool Flow\n\n1. `search_products` for exact SKU, product family, or dimensional phrase.\n2. `get_product` for verified product facts and canonical product URL.\n3. `get_pricing` and `check_inventory` for live commercial facts.\n4. `get_shipping_estimate` when destination and quantity are available.\n5. `compare_alternatives`, `pack_calculator`, or `inventory_status` when the buyer is exploring fit, alternatives, or warehouse stock.\n6. `get_cart_handoff_candidates` when an agent needs a compact list of priority SKUs with ready `create_cart_url` arguments.\n7. `create_cart_url` only after the buyer selected the exact SKU and quantity.\n\n## No-Match Rule\n\nWhen the requested dimensions, SKU, material, closure type, printer type, adhesive type, color, or pack count do not match an AI_APPROVE product, return no exact match. Do not label a nearby product as exact.\n";
export const mcpToolsJson = "{\n  \"endpoint\": \"https://mcp.packrift.com/mcp\",\n  \"guardrails\": [\n    \"AI_HOLD and AI_FIX products are excluded from purchase path recommendations.\",\n    \"No exact substitute should be returned unless dimensions and required attributes match.\",\n    \"Live price and availability should be confirmed before checkout handoff.\"\n  ],\n  \"tools\": [\n    {\n      \"description\": \"Search Packrift AI-approved packaging supplies by exact dimensions, material, color, strength rating, closure type, printer type, adhesive type, pack count, and SKU.\",\n      \"name\": \"search_products\"\n    },\n    {\n      \"description\": \"Return verified product facts for one AI-approved Packrift product handle.\",\n      \"name\": \"get_product\"\n    },\n    {\n      \"description\": \"Return current Packrift pricing for a selected approved SKU or variant.\",\n      \"name\": \"get_pricing\"\n    },\n    {\n      \"description\": \"Return current Packrift inventory signal for a selected approved SKU or variant.\",\n      \"name\": \"check_inventory\"\n    },\n    {\n      \"description\": \"Return Shopify draft-order shipping estimates for a selected cart.\",\n      \"name\": \"get_shipping_estimate\"\n    },\n    {\n      \"description\": \"Return priority AI-approved Packrift SKUs with ready create_cart_url arguments and required live-confirmation steps.\",\n      \"name\": \"get_cart_handoff_candidates\"\n    },\n    {\n      \"description\": \"Return a Packrift checkout handoff URL with MCP attribution after the buyer selects an exact approved SKU.\",\n      \"name\": \"create_cart_url\"\n    },\n    {\n      \"description\": \"Rank AI-approved Packrift alternatives for open-ended or competitor-style packaging requests.\",\n      \"name\": \"compare_alternatives\"\n    },\n    {\n      \"description\": \"Calculate required inside dimensions and return fitted box or mailer candidates with void-fill guidance.\",\n      \"name\": \"pack_calculator\"\n    },\n    {\n      \"description\": \"Return live total and location-level inventory for exact SKUs, handles, or variants.\",\n      \"name\": \"inventory_status\"\n    },\n    {\n      \"description\": \"Return tracked reorder, product, and copy-procurement-spec links for an AI-approved SKU or handle.\",\n      \"name\": \"get_reorder_link\"\n    },\n    {\n      \"description\": \"Return a tracked bulk quote URL for no-exact-match, large-volume, or procurement-review workflows.\",\n      \"name\": \"get_bulk_quote_link\"\n    },\n    {\n      \"description\": \"Explain why a nearby product should not be treated as exact and route to safe next actions.\",\n      \"name\": \"explain_no_exact_match\"\n    }\n  ],\n  \"transport\": \"streamable_http\"\n}\n";
export const noMatchPolicyMd = "# Packrift No Exact Match Policy\n\nUpdated: 2026-07-11\n\nIf no AI_APPROVE product matches a requested packaging spec, Packrift should return a structured no-exact-match result instead of a plausible substitute.\n\nUnsafe substitute examples:\n\n- Returning a 10 x 6 x 6 box when the buyer asked for 10 x 6 x 8.\n- Returning paper labels when the buyer asked for weather-resistant polyester labels.\n- Returning roll labels when the buyer asked for sheet labels.\n\nSafe next actions:\n\n- Ask the buyer to adjust the acceptable dimension range.\n- Link to Spec Finder.\n- Link to reorder-by-SKU when they know the exact Packrift SKU.\n- Route large or unavailable specs to quote intake.\n";
